INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1320591-ee203', 'stk-user2352', 'EE 203', 'info', '{"desc": "http://www.learnerstv.com/Free-Engineering-Video-lectures-ltv149-Page1.htm\nhttp://www.learnerstv.com/Free-Engineering-Video-lectures-ltv152-Page1.htm\nشروحات أونلاين فيديو مفيدة لشرح أغلب محتوى الكورس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203-electronics/120696/11", "user": "user2352", "ts": 1390044484000, "tid": 120696, "pn": 11}}', 1390044484000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1382401-ee203', 'stk-user8577', 'EE 203', 'info', '{"desc": "EE203\n\nمادة تشرح مبادئ عمل (الدايود، الأوب آم، الترانزستورز) وهي تعتبر مدخل للإلكترونكس، كورس تتعلم فيه أشياء كثير جديدة ما مرت عليك في الثانوي أو الفرشمان.\n\nالمواضيع التي يغطيها المقرر :\n\nالجزء الأول عن الأوب آم Operational Amplifier.\nالجزء الثاني عن الدايودز وكيف تستخدم في السيركتس عشان تعطيك voltage regulator أو limiter circuit أو rectifier.\nالجزء الثالث عن الترانزستورز بنوعيها BJT و MOSFT كل نوع بتدرس كيف تحلله و مراحل عمله.\nالجزء الرابع عن CMOS وهي أنك تعمل الديجتال لوجك قايتس باستخدام الترانزستورز.\n\nالكتاب المستخدم للمقرر:\n\nإذا عندك دكتور كويس شرحا مع أحد النوتات المعروفة للمادة ما تحتاج الكتاب الا مرجع و للهومورك.\nبالنسبة لي نوت الزاهر كان كويس.\n\nالمادة بشكل عام مو صعبة وسهل تفهم كيف تحل … المشكلة إذا سألك في الكونسبت وغالبا ما يركزوا على الكونسبت في المياجر بس الفاينال الكونسبت يكون فيه صعب (خاصة إذا الدكتور الزاهر كان يدرسها).\nاللاب حقها فيه بري لابات طويلة وتحتاج تستخدم برنامج (بي سبايس) بس اللاب نفسه و التجارب حلوة لأنك بتشوف الكلام اللي في اللكشر عملي.\n\nأنك تكون فاهم 202 كويس بيساعدك في بعض الأشياء في هالكورس.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203-electronics/120696/12", "user": "user8577", "ts": 1403689855000, "tid": 120696, "pn": 12}}', 1403689855000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1421913-ee203', 'stk-user5535', 'EE 203', 'info', '{"desc": "الكتاب سيء ، إذا كان يدرسك وسام مصباح فأنت في غنى عن الكتاب و أحس إن الكورس هذا سهل ، بالنسبة لي أسهل من ٢٠٢ لأنه ما فيه تحليل كثير للسيركت ، بس اذا عرفت نوع الامبليفاير او الدايود أو الـbjt او mos راح تعرف اي قانون تستخدم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203-electronics/120696/13", "user": "user5535", "ts": 1422124481000, "tid": 120696, "pn": 13}}', 1422124481000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1422103-ee203', 'stk-user9496', 'EE 203', 'info', '{"desc": "كورس مو صعب ،\n\nالكتاب مضيعة وقت\n\nالكورس عبارة عن : اوبريشينال امبليفايرز + دايودز + ترانزيستورز ( بي جي تي وموسفيت ) + ديجيتال ابليكيشنز للترانزيستورز\n\nبنظري الكورس سهل بس ذاكر اول ب أول", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203-electronics/120696/14", "user": "user9496", "ts": 1422199223000, "tid": 120696, "pn": 14}}', 1422199223000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1422981-ee203', 'stk-user8581', 'EE 203', 'info', '{"desc": "المواضيع التي يغطيها المقرر\n\nالكورس مهم وعبارة عن شرح لأساسيات electronics وهذي المواضيع الي يغطيها الكورس :\nOperation Amplifiers\nDiodes\nBipolar Junction Transistors\nMOSFET Transistors\nDigital Circuit Design\n\nالمواضيع قليلة لكن في كل كلاس راح تاخذ شي جديد وبما أن اغلب المواضيع جديدة فنوعا ما بعض الطلاب يواجهون صعوبة خصوصا في بداية السمستر فحاول تتابع اول بأول عشان تفهم الكونسبت\n\nالكتاب المستخدم للمقرر\nيمكن يستخدم كمرجع في بعض المواضيع لكن اكثر من دكتور نصحنا ما نذاكر منه + الي اشوفه انه ملخبط + فوق مستوى الطلاب بدرجة كبيرة فحاول ما تذاكر منه … اللهم الاسئلة الي في نهاية كل شابتر يمكن تفيدك …\n…\n- نزل عند دكتور ممتاز لأنه راح يوفر عليك ساعات من المذاكرة سواء من الكتاب او النوتة وخله هو مصدرك الأول للمذاكرة .\n\n- تابع اول بأول … الكورس اغلبه كونسبت وحفظ قوانين كثيرة فحاول تفهم في الكلاس + سو ملخص خاص فيك للقوانين ولا تتأخر لأنه تقريبا كل كلاس تاخذ شي جديد.\n\n- حل اسئلة الهومورك بنفسك ( على الاقل حاول ولو مافهمت ارجع للمانول سلوشن ) حلك للاسئلة راح يخليك تكون جاهز للميجر بنسبة كبيرة الي يبقى عليك مراجعة بسيطة للكونسبت وحل اولداقزام او اثنين والفل مارك مضمون ان شاء الله .\n\n- اذا كان د.الزاهر هو الكوردنيتر فأغلب الميجر راح يكون conceptual فحاول تكون فاهم والكورس عكس 202 … الـ analysis فيه اقل + اذا كانت المياجر نوعا ما سهلة فأنتبه من الفانيل .\n\nوبأختصار الكورس انت الي تحدد مستواه : اذا تتابع اول بأول راح يكون سهل او بالكثير متوسط واذا صرت عند دكتور لك عليه او ما كانت متابع الماتيرال اول بأول راح تعتبره من اغث الكورسات**.**\n\nهذا رابط فيه ملفات مهمة للمادة :\n**https://www.mediafire.com/?ddr9yp287j26nc2**\n\n- نوتة الزاهر\n- اولداقزامات للفاينل والمياجر\n- كويزات لـ راغب & السنيدي …\n- ملفات للاب\n\n\" ملاحظة \" هذا الملف من تجميع احد الطلاب الله يجزاه خير و حملته من فترة طويلة وللأسف ضاع رابط الموضوع \" اللهم اضفت عليه نوتة الزاهر لـ 142 .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203-electronics/120696/15", "user": "user8581", "ts": 1437935154000, "tid": 120696, "pn": 15}}', 1437935154000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473926-ee203', 'stk-mr.a1', 'EE 203', 'info', '{"desc": "Term 162 with MOHAMMED ABUELMA’ATTI\n\nجودة المقرر بشكل عام\nمقرر أساسي لطلاب الكهرباء ، ويعتبر مدخل للهندسة الالكترونية.\n\nالمواضيع التي يغطيها المقرر\nمواضيع المقرر بالترتيب:\nOperational Amplifier\nDiode (Rectifieres & Clippers)\nTransistors: BJT & MOSFET (Amplifiers)\nDigital Logics (CMOS)\nالمواضيع تعتبر قليلة نسبيا ، لكن كلها أشياء جديدة تمر عليك.\n\nالكتاب المستخدم للمقرر\nالكتاب كويس كمادة علمية ، لكن المذاكرة منه مملة.\n\nالأسئلة والأمثلة المستخدمة في المقرر\nأمثلة الكتاب جيدة جدا للفهم ، بالنسبة للأسئلة ما ذاكرت منها.\n\nمدى فائدته في الناحية التطبيقية\nمهم جدا لأي شخص تخصصه هندسة كهربائية ، خصوصا اللي بيتابع في مجال الالكترونيات.\n\nملاحظات:\n١. المادة قصيرة لكن تحتاج متابعة أول بأول ، لازم تذاكر كل شيء في يومه.\n٢. إحرص على الدكتور الممتاز في شرح المادة ، خصوصا الدكتور اللي يعلمك كيف تحل بدون ما تحفظ قوانين كثير ، مثل د. محمد أبو المعاطي.\n٣. الدكتور اللي تاخذ معه هو راح يكون مصدرك لمذاكرة المادة. الكتاب عام جدا ، ولو بتبحث عن نوت خارجي ممكن تلاقي فيه بعض الاختلافات عن اللي تسمعه في الكلاس ، فبالتالي يسبب لك تضارب.\n٤. ضروري جدا جدا جدا إنك تطلع فاهم الكورس مضبوط ، خصوصا إن EE 303 يعتبر متقدم بمراحل على EE 203.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203-electronics/120696/18", "user": "Mr.A1", "ts": 1495924082000, "tid": 120696, "pn": 18}}', 1495924082000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1487592-ee203', 'stk-red_black', 'EE 203', 'info', '{"desc": "بدأت فيه هذا الفصل و المخاوف تأكلني بصراحة. لا أدري إن كان يسيراً على طلاب الهندسة الكهربائية فربما درسوا أشياء تمهد له في مادة 200 أو 206 أو أياً كان ما يدرسونه قبله، و لكني طالب هندسة حاسب لم أدرس سوى 202 و مختبرها 212 و أجد نفسي “مضيعاً” منذ البداية. مصطلحات كثيرة لم تمر علي من قبل و لكن سير الدروس و شرح الكتاب (الذي يبدو أنه مضيعة للوقت حسب رأي الأغلبية) يفترضان أنني درستها بالفعل.\n\nيقولون اكتساب الدارة المفتوحة Open loop gain في المضخم العملياتي Op amp و أنا أقول “أين الدارة! لا توجد عناصر متصلة بشكل يغلق الدارة لكي تعمل أصلاً!”. فجأة صرت أرى رمز الأرض ground الذي لم أره مرة واحدة طيلة دراستي ل 202. و يقولون common mode rejection و هذا أيضاً لم أسمع به في حياتي. يقولون تردد و إشارة و تغذية استرجاعية feedbackو هذه أشياء لم تمر علينا قط في 202.\n\nالله المستعان. هذا الفصل سيمتلئ بالـ “حربقة” كما يقال.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203-electronics/120696/20", "user": "Red_Black", "ts": 1518276206000, "tid": 120696, "pn": 20}}', 1518276206000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1492666-ee203', 'stk-abdullah2015', 'EE 203', 'info', '{"desc": "أخذت الكورس في ترم 172 مع الدكتور محمد القحطاني\n\nالمواضيع التي يغطيها المقرر:\nOperational Amplifier\nDiode\nBipolar Junction Transistor\nMOSFET Transistor\nCMOS LOGIC GATE\nPass-Transistor Logic\n\nفي أول أربع مواضيع راح تتعلم باختصار كيف تسوي Circuit Analysis لدوائر كهربائية فيها Op-Amp و Diode و Transistor سواءً كان Bipolar أو MOSFET وكذلك كيف تستخرج الGain للAmplifier\nلما أقول Circuit Analysis أقصد بتتعلم كيف توجد الكرنت والفولتاج في أي فرع في الدائرة الكهربائية، وتوجد الThevenin equivalent circuit زي ما كنت تسوي في EE202 لكن هنا على دوائر إلكترونية (نفس المنطق تقريبًا).\nبخصوص الGain المقصود به الكفاءة “Efficiency” يعني الOutput Voltage على الInput Voltage … مثلًا كم مرة الـ Input Voltage راح يتضخم؟ ممكن الGain يكون 5 أو 6 يعني لو حطيت Input Voltage على الدائرة الكهربائية 0.5 فولت، الـ Output Voltage راح يكون 2.5 أو 3 فولت. (بالمناسبة، الGain ممكن يكون أقل من 1، يعني الOutput Voltage للـ Amplifier ممكن يكون أقل من الـ Input Voltage).\nفي آخر موضوعين راح تتعلم كيف تطبق الدوائر الرقمية اللي تعلمتها في EE200 على هاردوير باستخدام Transistor ويعتبر جزء سهل جدًا إذا كنت فاهم الEE200.\n\nالكتاب المستخدم للمقرر:\nhttps://images-na.ssl-images-amazon.com/images/I/515XShqlhDL._SX406_BO1,204,203,200_.jpg\nhttps://www.amazon.com/Microelectronic-Circuits-International-Sedra/dp/0199738513\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nالأمثلة الموجودة في الكتاب ممتازة للفهم.\n\nمدى فائدته في الناحية التطبيقية:\nالمقرر مهم جدًا لأي مهندس كهربائي مهما كان توجهه لأن الإلكترونيكس داخلة في كل مجالات الهندسة الكهربائية تقريبًا.\nإضافات:\n1- الكورس سهل if and only if ذاكرته أول بأول.\nهذا الكورس شوي يختلف عن باقي الكورسات، صحيح إنه الكونسبت فيه شوي ثقيل ويبي له متابعة، لكن إذا فهمته فتقريبًا ضمنت الكورس لأن الأفكار اللي في الكورس قليلة، ومجال التريكات محدود.\n2- في بداية السمستر الكثير يكون ضايع بخصوص مصدر المذاكرة، وخلاصة اللي توصلت له إنه خل دكتورك اللي تنزل عنده الكورس هو مصدرك، يعني أكتب معاه نوت في الكلاس، وذاكر من سلايداته، وركز على أسئلة الهوموورك اللي يعطيك إياها. لو بحثت في النت أو رحت لنوت خارجي راح تلاحظ اختلاف عن اللي تاخذه في الكلاس، وراح يصير فيه تداخل أو تضارب في المعلومات. والكتاب، في نظري، ما ينفع كمصدر رئيسي للمذاكرة.\n(وهنا تتضح أهمية اختيار الدكتور في هذا الكورس خصوصًا).\n3- خذ بعين الاعتبار إن الPrelab لهذا الكورس راح يأخذ من وقتك الكثير خصوصًا على بدايات السمستر، لأن بيكون أول مرة تتعامل فيها مع Pspice .\n4- اللاب في هذا الكورس ممتع وسهالات، كونك تطبق نفس اللي تعلمته في اللكتشر بالضبط. بخصوص الريبورت ما راح يكون فيه ريبورت في معظم التجارب، فقط ورقة فيها جداول وفراغات تعبيها وتسلمها على نهاية اللاب وخلاص، لكن راح يكون فيه Full report لثلاث تجارب تسويه مرة واحدة في السمستر، وهذا فيه شغل.\n5- فهمك للEE202 مهم جدًا في هذا الكورس، وأخص بالذكر Ohm’s Law وNodal Analysis وMesh Analysis وVoltage Divider و Thevenin Circuits، صحيح إنه طريق تطبيقهم شوي مختلفة هنا، لكن زي ما ذكرت كلهم يشتركون في نفس المنطق تقريبًا.\n\nبالتوفيق للجميع 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203-electronics/120696/23", "user": "Abdullah2015", "ts": 1526633610000, "tid": 120696, "pn": 23}}', 1526633610000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1513336-ee203', 'stk-breaktheunbreakable', 'EE 203', 'info', '{"desc": "ما عندي شيء أقوله غير أن المادة سهلة وقصيرة ومترابطة وتعتمد بشكل كبير على المدرس اللي تنزل عنده. نزل عند واحد شريح وما يجيب أشياء صعبة ويعطي درجات جيدة. مصادر المذاكرة للمادة سهلة، وطبعا ابتعد عن الكتاب. استعمل سورسات الجامعة (نوتات المدرسين)، سمري وقوانين الكتاب نهاية الشابتر، وفي بعد نوتات لجامعات ثانية ممتازة تجي، وحل أسئلة الكتاب المشابهة للأولد اكزامز وحل أولد اكزامس ووضعك بيكون ماشي.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203-electronics/120696/24", "user": "BreakTheUnbreakable", "ts": 1564923617000, "tid": 120696, "pn": 24}}', 1564923617000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p132316-ee203', 'stk-user1091', 'EE 203', 'info', '{"desc": "بسم الله\n\nيا هلا بأخوي الطير وأخوي بايسن\n\nAl-sunaid\n\nالسنيدي : ممتاز ويمدحونه كثير بس يقولون إنه حق كرف\n\nوصراحة أحسن واحد مر علي في 203 هو الشهراني\n\nعلى العموم ترا اللستة يمكن تتغير\n\nفإذا حطولك الشهراني نزل عنده وأنت مغمض\n\nوترا بعض الشباب يغير التخصص علشان هالمادة\n\nلأنها أربع ساعات ويحتاج لها مدرس حق شرح\n\nفإذا أخذتها مع مدرس شرح ضعيف بتحصل المادة صعبة\n\nوعلى أيام الشهراني ما كنا نفتح الكتاب إلا نادرا ونوته يكفي\n\nالله يوفقك أخوي الطير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee203/53330/4", "user": "user1091", "ts": 1164034119000, "tid": 53330, "pn": 4}}', 1164034119000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p635696-ee203', 'stk-user3489', 'EE 203', 'info', '{"desc": "8\n8\n8\nإلا له دخل …\n\nوهم مأكدين علينا بداية السمستر إن الآفرج بيكون كومن …\n\nوقالولنا إن السمستر الماضي ما كان كومن بس الحين بيصير كومن …\n\nوحتى كل ما سألناهم عن الآفرج … يقولون … ما أعرف لأن في دكاترة ما بعد خلصوا تصحيح…\n\nوالله نظام الكومن … ظلم … ظلم … ظلم …\n\nأشياء دكتور رككككز عليها… ودكتور ثاني مر عليها بسرعة وأحيانا يقولك “هاذي ما بتجي” وتجي بالفاينل…\nوفرق كبيييييييييييييييييير في التصحيح …\nوالله العظيم إن الفرق في التصحيح كبير جدا جدا جدا … وشفت بعيني دكاترة ينقصون بالجملة … ودكاترة يدفونك لين تطفش …\nوفي النهاية كومن ؟!؟!؟#$#%^$#^%\nفي دكتور نزل قريدات الفاينل يشوفونها الطلاب…\nودكتور حط القريد النهائي في الترانسكربت على طول …\n\nلكن يلا … خلصنا مواد ليفيل 2 … وخلصنا من مواد الكومن … والله إني خايف تنتقل عدوى الكومن لليفل 3 كمان …\n\nملاحظة :\nلا يظن البعض إني أنتقص من الدكتور العبسي …\n\nوالله دكتور محترم جدا جدا … وبحر من العلم والأخلاق…\nولو رجع بي الزمن … بنزل الــ203 عنده مرة ثانية … 🙂 …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203/89986/9", "user": "user3489", "ts": 1276715151000, "tid": 89986, "pn": 9}}', 1276715151000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p636019-ee203', 'stk-deeeer', 'EE 203', 'info', '{"desc": "انا اعطيكم العلم الوكاد الاختبار كومون والافرج كومون وبس\n\nيعني القريدات على حسب الدكتور اذا المطلوب عليه انه الافرج يكون سي\nومن فين لفين البي وزي كذا راجعتله بس يلتزم بالافرج انه سي\n\nوترا احنا اول ناس اتظلمنا في هذا الموضوع قبل سنتين واتلسعنا والعب يا ولد\n\nيعني دكتور طالب فوق الافرج ب7 درجات يعطيه c+ او b وما حد حيقوله شي طالب تحت الافرج ب5 درجات يعطيه سي ولا دي بلس وزي كذا\nاهم شي القسم يحب يستعرض عليكم اول سنه عشان تشدوا حيلكم\n\nبعدها كل الشغل عند الدكتور و3 ليفيل ما فيه افرج كمون اذا كترو حطو الفاينل كمون\n\nوبعدين لا تقولو انظلمنا لانه النظام على الجميع وفي ماده تتلسع وماده تنبسط", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203/89986/15", "user": "deeeer", "ts": 1276730687000, "tid": 89986, "pn": 15}}', 1276730687000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1126349-ee203', 'stk-user5825', 'EE 203', 'info', '{"desc": "السؤال الثاني من جد لحسلي مخي ما فهمت ايش يبغى مع اني قريته في النوت بس ما اتوقعت يجيبوا شيء زيه 😆\n\nوالثالث اعتقد اسهل بالتي مودل بس ماكنت مذاكرها\nلكن اللي حافظ رسمة الباي مودلز وقوانين الـ V0 , Rin و الـ Rout يقدر يحلها مع ان قانون الRo طوييييييل فسحبت عليه 😁\n\nنقول خيرة ياشباب ان شاء الله الفاينل وهو المهم يجي سهل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203-121/131892/129", "user": "user5825", "ts": 1354168815000, "tid": 131892, "pn": 129}}', 1354168815000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1500110-ee203', 'stk-blo998', 'EE 203', 'info', '{"desc": "بنقل لك تجربتي في هذي الماده يا صاحبي, طبعا ع العموم اذا كويز واحد جبت فيه صفر لا تشيل هم ما بيأثر كثير ان شاء الله.\n\nانا في البدايه كنت اذاكر من الكتاب و احاول افهم الكونسبت كويس, و قبل اول ميجر جلست اتدرب ع الاولد اقزام.\nالمهم اني عيدت بميجر 1 و اذكر اني جبت حول 54 و الافرج اذكر حول ال 70.\n\nالميجر الثاني غيرت طريقة الدراسه صرت اركز ع اسالة الكتاب و احلها كلها, بعد ما احل اتاكد من الحل من المانيوال سلوشن. و احل وحده او اثنين من الاولد اقزام.\nو اظن كنت احل من الادشن القديم لانه الكتاب الجديد ما كان له مانيوال سلوشن.\nالزبده ميجر 2 طلعت ب 84 و الافرج اظن كان تحت ال 70.\n\nقبل الفاينل لاحظت انه اغلب الاخطاء حقتي كانت في عدم فهمي للسؤال بشكل مناسب.\nالمهم الفاينال ذاكرت مثل مذاكرتي لميجر 2 و كنت اي سؤال احس اني موب فاهمه اسأال الدكتور\nو الحمدلله الفاينل اذكر كنت اعلى درجه بالكلاس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee203/180257/4", "user": "blo998", "ts": 1538229156000, "tid": 180257, "pn": 4}}', 1538229156000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p563757-ee203', 'stk-_1012', 'EE 203', 'info', '{"desc": "اسئلة الكتاب مافي افضل منها لكنك مو شرط تحلها دايركت افضل شيء انك تواجه اسئلة ما تعرف تحلها افضل من تلاقي اسئلة سهلة وحلها ما يسوي لك اي نتيجة\n\nاذا شفت نفسك فاهم الكونسبت مضبوط حاول تحل اولد اقزامز وبعدها حل اسئلة الكتاب واكون صادق معك فيه اسئلة صعبة خصوصا الشابترز 4 و 5 لكن شابتر 3 اسئلته سهله واتوقع اسئلة الاقزام راح تكون اصعب\n\nبرجع هنا اذا لقيت شي يفيدك يا السيد بعيد المنال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203/85245/2", "user": "_1012", "ts": 1268343580000, "tid": 85245, "pn": 2}}', 1268343580000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p563765-ee203', 'stk-user6200', 'EE 203', 'info', '{"desc": "اولا اشكرك اخووي من اعماق قلبي على ردك\n\nلكن شابتر 3 هو سهل ادري لكن فيه تمارين ما عمره شرح الدكتور ولما سالته عنها قال هذي يا مو مطالب فيها يا تاخذها بعدين في شباتر متقدمه او اعلى من مستوانا لاننا بدينا من شابتر 3 مو من 1 هذا اللي فهمته منه!!\n\nولا ادري بصراحه احترت بهالماده كثيييييير\n\nومشكور على اهتمامك مقدما", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203/85245/4", "user": "user6200", "ts": 1268344124000, "tid": 85245, "pn": 4}}', 1268344124000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p976515-ee203', 'stk-ahmad_ajr', 'EE 203', 'info', '{"desc": "كورسات المستوى الثاني ee 203 , ee , 205 و ee 207 صارت كومون ،\nدرجة الكلاسوورك تعتمد على أفرج الكلاس والجريد النهائي يعتمد على أفرج جميع السكاشن\nفما أعتقد أن الدكتور القحطاني بيعطي أعلى واحد b لو كانت درجاته مرتفعة في المياجر والفاينال.\n\nاللي أبغى أسأل عنه هو مستوى شرح القحطاني ، هل يعتبر شريييح ولا عادي .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203/119031/4", "user": "ahmad_ajr", "ts": 1327923600000, "tid": 119031, "pn": 4}}', 1327923600000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1020498-ee203', 'stk-m77a_alkhraimi', 'EE 203', 'info', '{"desc": "السلام عليكم,\nياشباب الله يرحم والديكم اللي يعرف مدرس خصوصي لهذي الماده يعطيني رقمو ضروري جدا جدا انا صارتلي ضروف صحيه واتغيبت عن محاضرات كثيره وبشكل متواصل وحاولت اذاكر وافهم الماده بنفسي بس ماقدرت الماده صعبه صراحه والميجر الاسبوع الجاي وانا تقريبا ماني فاهم اي شي من المتيريل حق الميجر , ولو عندك اكثر من مدرس حط ارقامهم كلهم لاني إلى الان كلمت مدرسين واحد اسمه عبيد والثاني محمد(هذا طالب يحضر الدكتورا عندنا في الجامعه) وثنينهم اعتذروا.\nاسف على الاطاله بس هذا من سوء الموقف اللي انا فيه الله يعينى وياكم على هذي الجامعه…\nهذا رقمي انتظر تفاعلكم على احر من الجمر…\n\n0546558893 أحمد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee203/124057/1", "user": "M77a_Alkhraimi", "ts": 1334062466000, "tid": 124057, "pn": 1}}', 1334062466000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1173936-ee203', 'stk-lord', 'EE 203', 'info', '{"desc": "وعليكم السلام و رحمة الله وبركاته\n\nتقييمي للمادة :\n\nالمادة مافيها أي نوع من أنواع التعقيد أو الصعوبة\nبمنعى , مع التركيز مع المدرس و بذل الجهد الكورس في متناول اليد\nممكن الصعوبة الوحيدة في الكورس ان فكرته جديدة ومبادئ أول مرة تمر عليك\nبما انه أول كورس الكترونكس ف حاول انك تفهم الكونسبتس من البداية و تتعود عليها و \" تدخلها براسك \"\nوبعد كذا الكورس كله عمليات حسابية بسيطة و تحليل سيركت زي ال 201 .\n\nأفضل مصدر للمذاكرة ينقسم ل قسمين :\n\nالأول لو كنت تبي تجيب درجات كامله في المياجر و الفاينل\nف لابد أن تفهم و \" تحفظ \" نوت حسن راغب\nلأن الأسئلة حرفياً نسخ لصق من النوت .\n\nالثاني لو كنت تبي تفهم الكونسبتس وتعرف ايش الالكترونكس ك طالب كهرب\nف انصحك بقراءة الكتاب قراءة مركزة\nوما يضر الاستعانة ببعض مقاطع اليوتيوب لترسيخ المفاهيم\n\nأكبر خطأ انك تختار الطريقة الأولى و تترك الثانية أو العكس\nأفضل شئ انك تتبع كل الطريقتين لكن كل وحده لها وقتها\nالأولى تكون قبل المياجر و الكويزات\nو الثانيه تكون على طول السمستر\n\nو نصيحه مني أبذل جهد في المادة هذي كأنك تذاكر لمادتين !\nيعني ل 8 كريدتس مو بس 4 كريدتس\nلأنك على قد الجهد اللي راح تبذله في ال203\nال303 ( الكترونكس 2 ) راح تسهل عليك\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee203/139565/2", "user": "Lord", "ts": 1359626811000, "tid": 139565, "pn": 2}}', 1359626811000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1362626-ee203', 'stk-big_h', 'EE 203', 'info', '{"desc": "انا كمان كلمت الدكتور معن كوساوقالي اليوم في اجتماع مع التشيرمان\nفي 20 طالب كانو مسجلين فالكورس واتوقع عدد مرة كافي عشان تنزل المادة , غير ان الكورس مطلوب في قسم هندسة النظم والكمبيوتر اتوقع وهذا حيشكل ضغط عليهم انه ضروري تنزل المادة\nعموما اتفاءلوا خير الموضوع حينحل باذن الله\nطمنا يا منصور ايش يحصل معاك , وانا حاكلم الدكتور معن يوم الاحد واعرف منه ايش حصل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203/160802/16", "user": "Big_H", "ts": 1399524057000, "tid": 160802, "pn": 16}}', 1399524057000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1330816-ee203', 'stk-user7502', 'EE 203', 'info', '{"desc": "بالنسبة ل 213\nإلا تنفع\nشرحه يمكن اللي ما ينفع\nأنا أخذتها معه\nسلايداته إذا ركزت عليها و ذاكرتها زين تبي تمشي أمورك\n+ الكتاب (ضروري) ترجع له كـ مصدر لفهم المادة .\nـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ\nبالنسبة ل 203\nذاكر نوتة حسن راغب و حل الأمثلة والأسئلة اللي فيهااا . المادة هذي تحتاج شغل بقدر ما تحل أكثر تفهم أكثر ولا تستعجل عليها صعوبتها تكمن في البداية فقط .\nموفقيـــن", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee213-ee-203/156787/4", "user": "user7502", "ts": 1392574168000, "tid": 156787, "pn": 4}}', 1392574168000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1368218-ee203', 'stk-abo-zahrah', 'EE 203', 'info', '{"desc": "ياشباب اللي عند حامي والزاهر ممكن يعطونا العلم دكتورنا ليله طوييل السي من كم او على الاقل الكت بوينت للباس ؟؟\n\nوجزاكم الله خير …\n\nنصيحة من اخ لاخوانه\nالاولى:-\nفي الكورس هذا بالذات او اي كورس الكترونكس مستقبلا اذا شفت الزاهر موجود يدرس في الترم اللي انت بتاخذها فيه لاتنزلها ابد انحش\nعلى قولتهم حط رجلك\nالثانية:-\nالدكتور محمد السنيدي اذا نزلت معاه وتبي تطلع معاه بقريد اضرب الكريدت للكورس باثنين واشتغل على هذا الاساس\n\nنصائح من ذهب 👋 👋 👋", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee203/161355/5", "user": "Abo-Zahrah", "ts": 1400676455000, "tid": 161355, "pn": 5}}', 1400676455000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1163826-ee203', 'stk-user5800', 'EE 203', 'info', '{"desc": "استاذ ممتاز جداً ، شريح\nو يجاوب على اسئلة الطلاب كلها\n( اخذت عنده كورس 204 … for non ee )\nوكانت تجربة ايجابية معه …\nونوت السبورة عنده مرتب …\nتصحيحاته للمياجر دقيق الى حد ما …\nلكنه يتهاون احيانا في تصحيح الكويزات\nيعني يقول اني رفعت فيكم عشان كلاس وورككم يرتفع\nجريداته ،، المادة كانت افرج عااام فما بيده حيله…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/t-noman-ee203/138337/2", "user": "user5800", "ts": 1358120334000, "tid": 138337, "pn": 2}}', 1358120334000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p931597-ee203', 'stk-ieee', 'EE 203', 'info', '{"desc": "حسنا\n\nطيب…ميجر ون مو نهاية العالم ومازال لديك الكثير من الفرص.\n\nما أنصحكم به باختصار هو أن تتوجه لمدرس قدير خلال ساعته المكتبية من أمثال:\nد.محمد طاهر أبو المعاطي، د.منير العبسي، او د. سعد الشهراني\n\nفهم من خيرة القسم في هذا التخصص. نظم أسئلتك وتوجه إليهم وأنا متأكد أنك لن تندم على الأقل من ناحية الفهم النظري.\n\nعمليا، هذه المادة بحاجة لحل العديد من المسائل وأنصحك بسلسة تسمى Schaum’s Outline of Electronic Devices and Circuits\nعلى ما أذكر أن الكتاب لدى مكتبة الجامعة، قم باستعارته وعليك بحل قدر ماتستطيع من أفكار.\n\nتمنياتي لكم بالتوفيق!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-203/114977/3", "user": "ieee", "ts": 1321442272000, "tid": 114977, "pn": 3}}', 1321442272000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p862120-ee203', 'stk-user4571', 'EE 203', 'info', '{"desc": "شوف حبيبي المادة خذتها الترم الماضي وغثتني لاني كنت ساحب عليها\n\nتبي تمشي بها مضبوووط…,\nاول باول لان منهجها طويييل مره\nوانا اشوف ان الماده تقدر تقول انها تميل للحفظ\nيعني تحفظ القوانين والاشكال.>>هذي لميجر 2 وانت ماشي\nالماده تراها سهله><<<بس جبت بها قريد جاب فيني العيد لاني مثل ما قلتلك كنت ساااااحب عليها\n\nشد حيلك واي شي تبيه غير الشرح…>ض1 ابشر من عيوني", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/the-circuits-in-ee203/109273/4", "user": "user4571", "ts": 1309582036000, "tid": 109273, "pn": 4}}', 1309582036000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p862797-ee203', 'stk-extensa', 'EE 203', 'info', '{"desc": "شف ترى تبي تعب نفسك اذا بديت تقارنها بهذا الشكل … وكل ماجيت تبي تحل تحول من شكل الى اخر …\nفنصيحتي لك : خلك مع الشكل الي فهالكورس وصدقني راح تتعود عليه …\nاهم شئ بهالمادة افهم … صدقني لو فهمت مضبوط يجي الميجر ولا الفاينل وانت مرتاح … معليش \" يالتفاصيل \" اخالفك في وجهة نظرك …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/the-circuits-in-ee203/109273/5", "user": "extensa", "ts": 1309729961000, "tid": 109273, "pn": 5}}', 1309729961000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p803180-ee203', 'stk-x_zero', 'EE 203', 'info', '{"desc": "باختصار لا تذاكر من الكتاب لانه معقد جدا جدا جدا\n\nانصحك تبحث بالانترنت شرحها أسهل من الكتاب\nفيه بعد open course ware لكن مشكلتها انها ما راح تفهم منها الا اذا فهمت شرح المدرس منها وقتها تقدر تذاكر منها\nبمعنى آخر هي محطوطة عشان يشرح منها المدرس مو عشان تذاكر وتفهم منها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee203/103920/5", "user": "X_zErO", "ts": 1298969624000, "tid": 103920, "pn": 5}}', 1298969624000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p889810-ee203', 'stk-daredevil', 'EE 203', 'info', '{"desc": "ال phys ماده من الاساس صعبه وكل طلاب الكهرب يشتكون منها بس انا نصحتك تاخذها في 111 لانها بتفيدك في ال ee 203 وتفتك منها قبل ماتتعمق في التخصص اما من ناحية ال chem فلا تشيل همها لان التشابه في تشابتر واحد بس وبتدرسهم باالتفصيل في كل الكورسين فما اشوف اي مشكله لو تاخذ ال phys قبل ال chem …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee/111020/5", "user": "DareDevil", "ts": 1313984461000, "tid": 111020, "pn": 5}}', 1313984461000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p934685-ee203', 'stk-_student', 'EE 203', 'info', '{"desc": "نبذة عن الكورس:\nEE 203 - Electronics I (3-3-4)\n\nDiodes: models and circuit analysis. Diode applications (rectifiers and others). Transistors: bipolar junction, junction field effect and metal-oxide-semiconductor field effect (BJT, JFET & MOSFET). DC and small signal AC analysis. Amplifier configurations. Differential Amplifiers. Digital logic families (TTL, ECL, I2L, and CMOS circuits).\n\nبإختصار الكورس يتكلم عن الدايود وعن نوعين من الترانزستور.\n\nأنا من رأي أنك تنزلها السمستر الجاي وتخلص منها لأن المادة شوي ثقيلة من ناحية الكونسبت ويحتاج لها زيادة تركيز، ركز عليها كويس وحل كل المسائل وإن شاء الله تطلع بأحلى قريد. ممكن تاخذ فكرة عن أسئلة مياجره من خلال هذا الرابط:\nhttp://www1.kfupm.edu.sa/ee/OCW/ee203.htm\n\nأنا أخذتها مع وسام مصباح في ترم 102، وكان شرحه رهيب من سلايدات يحتاج لك بس تصحصح معاه من أول الكلاس لآخره، وكان يشرح من قلب ويطلق، وكان تصحيحه شديد شوي، وكويزاته متوسطة تميل للسهولة. وممكن تطلع على صفحته في قسم التقييم:\nhttp://skfupm.kfupm.edu.sa/vb/showthread.php?t=58372\n\nوعندك بدر عبدالله مع أنه ما درسني لكتشر بس ما يمدحون شرحه مع أنه متساهل في التصحيح، هذا السمستر ما أشوفه موجود وجا مدرس جديد مكانه، وإن شاء الله يرجع. وهذي صفحته في قسم التقيم:\nhttp://skfupm.kfupm.edu.sa/vb/showthread.php?t=58357\n\nبقية المدرسين مادري عن وضعهم في هالكورس. مع العلم أن مياجر الكورس كومون، بس اللي أسمعه حاليا من الشباب أن تقسيمة الدرجات موحدة في الوضع الحالي.\n\nإن شاء الله تكون معلوماتي لك كافية لإتخاذ قرارك، مع تمنياتي لك بالتوفيق وأحلى القريد.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/115295/3", "user": "_student", "ts": 1321907993000, "tid": 115295, "pn": 3}}', 1321907993000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1450469-ee203', 'stk-user8914', 'EE 203', 'info', '{"desc": "الكتاب هذا ذاكرت منه للسيركت والحمدلله طلعت بقريد ممتاز\nكتاب جميل وسهل الفهم ويعطي مسائل كثيره\nhttp://www.portcity.edu.bd/ELibrary/EEE/fundamentalsofelectriccircuits.pdf\n\nنصيحتي لك اذا انت من طلاب الكهرب وتوك بادي\nاهتم ثم اهتم بالكتب ومسائلها واذا كان كتاب الماده سيئ مثل الee203 ابحث عن كتب في النت", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/circuit-i/173482/3", "user": "user8914", "ts": 1464256861000, "tid": 173482, "pn": 3}}', 1464256861000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1415555-ee203', 'stk-the_silver', 'EE 203', 'info', '{"desc": "مرحبا أخوي\n\nأخذت phys203 وكان بعض مواضيعها متشابه إلى حد ما مع ee203\nيعني تحس إن المادتين يكملوا بعض … بس أكيد فيها أشياء ومواضيع جديدة ومختلفة\n\nمستوى الصعوبة … الدكتور كان مسهلها كشرح وسلايدات … بس أحيانا يصعبها في الاختبارات\nيعني بشكل عام صعوبتها 6\\10 (بالنسبة لي)\n\nوتسلم على النصيحة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/167049/78", "user": "THE_SILVER", "ts": 1416997557000, "tid": 167049, "pn": 78}}', 1416997557000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p169874-ee203', 'stk-eekfupmee', 'EE 203', 'srcU', '{"html": "السلام عليكم ورحمة الله وبركاته<br><br>الرجاء مساعدتي في حل هذا المشروع جزاكم الله الف خير<br><br>التخصص هندسة كمبيوتر<br><br>Rl=250 ohms<br><br>​<span data-fid=\"stk-f169874-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f169874-0": {"name": "Term Project EE 203.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/64a73b85ebd7e494e89c7e3df6a87c4efc2ffbe4adc32fcb6bdddec2ef6553a1"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee203/56395/1", "user": "eekfupmee", "ts": 1179585741000, "tid": 56395, "pn": 1}}', 1179585741000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p273565-ee203', 'stk-abdulaziz22', 'EE 203', 'srcU', '{"html": "المرفقات فيها البروجكت كامل<br>قسمتة 4 ملفات لان المنتدى ما يرضى تحميل ملف كبير<br>مرتبة بالارقام<br>جمعهم بملف واحد والله يوفقك<br>حاول تشد حيلك توك في بداية الطريق<br><br>​<span data-fid=\"stk-f273565-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f273565-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f273565-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f273565-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f273565-0": {"name": "1.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/bc293418f3b6d08a8a125031ea4491e45a60d30cd80011dda969e06168fe0223"}, "stk-f273565-1": {"name": "2.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/dcdc152d3013bbfdfeee63c2580f592994ad2ab7b9bf31fdefe176aedbc2ff26"}, "stk-f273565-2": {"name": "3.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/60ec4e4f2cab1c7d83f4a8b253548ece2c80e5c03cffdca6347567a68bbf87dc"}, "stk-f273565-3": {"name": "4.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/108d260cc20ff197302df71ed7c9b6bbbb83cf0d376d127bbf48c327946a7b95"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/project-ee203/63660/4", "user": "abdulaziz22", "ts": 1213188169000, "tid": 63660, "pn": 4}}', 1213188169000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
