INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p955711-ee203', 'stk-user8246', 'EE 203', 'srcU', '{"html": "السلام عليكم<br><br>يا جماعة الخير عطانا الدكتور هذا البروجكت مو فاهمين كيف نطلع القيم<br><br>يعني لو واحد يقدر يعطينا موقع أو بعض الافكار في حله شاكراً لكم<br><br>111.JPG912×334 77.2 KB<br><br>​<span data-fid=\"stk-f955711-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f955711-0": {"name": "Design Project.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee203/117205/1", "user": "user8246", "ts": 1325237924000, "tid": 117205, "pn": 1}}', 1325237924000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p121677-ee203', 'stk-user1091', 'EE 203', 'srcP', '{"html": "بسم الله<br><br>للأسف أخوي ما عندي السلوشن<br><br>لكن في المرفقات تلاقي كوزات ومياجر<br><br>إن شاء الله تستفيد منها<br><br>الله يوفقك<br><br>​<span data-fid=\"stk-f121677-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f121677-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f121677-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f121677-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f121677-4\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f121677-5\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f121677-0": {"name": "EE203 041 E1.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/63530f9c89b6d983868b8042e06f4f4e6de62b7c272601a5964177d4f85d1acd"}, "stk-f121677-1": {"name": "EE203 041 E2.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/3dd2a335636bdd24369c28925255b46b32dbfc7ae392a0a6f5620b2b9c7bd717"}, "stk-f121677-2": {"name": "EE203 Q5 041.pdf", "v": "data:application/pdf;base64,"}, "stk-f121677-3": {"name": "EE 203 Q3 (052).pdf", "v": "data:application/pdf;base64,"}, "stk-f121677-4": {"name": "EXAM I (052).pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/47b412c45a72defb644f3998c8d0bb96624adaa0bf7141fef3cc9f24d67f26c1"}, "stk-f121677-5": {"name": "HW1 EE203.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/27a1fa42ecc4387fce2860ed363a9f1a56acc4fa26bd8c690c81c6f9b913c315"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/52320/8", "user": "user1091", "ts": 1159959795000, "tid": 52320, "pn": 8}}', 1159959795000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mzd-ee203', 'stk-mzd', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f80097", "n": "Dr. K Gasmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T212 EE203\n\nالتحضير : يعطيك ورقة وكل طالب يوقع.\n\nطريقة الشرح : يشرح من سلايداته. وشرحه عادي مافيه شيء مميز.\n\nالكويزات : سهله وعددها قليل\nالمياجر: كومن\nالفاينلات : كومن\nالتصحيح: الدكتور تصحيحه ممتاز ويدف كثير.\nالقريد النهائي: A\nالصوت: ممتاز واضح\nإضافات :\n- الدكتور حبيب واخلاقه ممتازة مشاء الله.\n- الدكتور خيار جيد لكن ليس الأفضل.\n- الدكتور متعاون بشكل كبير مع الطلاب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534481-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-gasmi/80097/54", "user": "MZD", "ts": 1653727290000, "tid": 80097, "pn": 54}}]}', 1653727290000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6200-ee203', 'stk-user6200', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98390", "n": "Dr. I Akram", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لاب ee 203\nهندي\n\nالتحضير : يحضر بشغلك باللاب يمر عليك ويسجل درجة عملك اذا خلصت\nطريقة الشرح : عادية جدا\nالكويزات : نظرية وسهلة مرره\nالمياجر:…\nالفاينلات :عملي ويقولك سجل النواتج وبس\nالقريد النهائي: اذا تبي ترتاح نزل معه\nالصوت: منخفض شوي\nإضافات : …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p743378-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/i-akram/98390/2", "user": "user6200", "ts": 1292257538000, "tid": 98390, "pn": 2}}, {"id": "stk-dr-f98372", "n": "Dr. Abdullah Badr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "092 كورس EE203\nالتحضير :يومي ينادي بالاسماء\nطريقة الشرح : سلايدات مررره ممتازة ويشرح من قلب بس الطلاب مايقهمون منه احيانا هو فاهم بس احيان مايعرف يوصل المعلومة بس لو ركزت معه راح تفهم 60 بالمية والباقي عليك\nالكويزات : بصراحة صعبة شوي\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: انا بالنسبة لي اعطيه a\nالصوت: واضح\nإضافات : تصحيحه يعجبك مررررهــ يعوض عن شرحه ههههه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p743380-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-badr/98372/2", "user": "user6200", "ts": 1292257755000, "tid": 98372, "pn": 2}}]}', 1292257538000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-better_4_ever-ee203', 'stk-better_4_ever', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98387", "n": "Dr. Mesbah Wessam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : يحضر اخر الكلاس ويدخل اللي يجي متأخر شوي\n\nالشرح: ممتاز الرجال صراحة بالشرح وانا من اعتقادي لانه يشرح على سلايدات وعلى السبورة يمكن بكورس مو نفس اللي ماخذة الحين ممكن مستواه يختلف.\n\nالكويزات: متوسطة غالبا ماهي بالصعوبة .\n\nالفاينلات : للحين ماخذناها دعواتكم بس 🙂\n\nالصوت: ممتاز مناسب جدا للبعيد والقريب.\n\nاضافات: انا الحين عندة ee 203 اول شهرين شديت حليلي معاه وكنت اكتب وكل شيء وفاهم كل شيء قاله سحت عليه ضاعت المعلومات ومو فاهم ولا شيء (الخلاصة اكتب معاه في كل الاحوال لانه بدون الكتابة اللي يكتبها في السبورة راح تضيع ولا بتفهم ولا شيء.\n\nوعلى فكرة ابدا مايحب واحد ماينتبه للشرح او يلعب بالجوال طرد برة الكلاس 🙂\n\nومعلومة ثانية راح تلاحظون انه يعرق كثير ودائما يشتكي حر المكان حر والناس متجمدة من التكييف (من زود الحماس) بس ماشاء الله عليه شرح ويكفيك واخلاق بعد\n\nاخر ملاحظة لا تطر منه درجات مايعطيك وجه ابد مايعطيك لو ايش يمشي عالمانيوال حرفيا.\n\nوسلامتكم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p844908-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mesbah-wessam/98387/8", "user": "BETTER_4_EVER", "ts": 1306774370000, "tid": 98387, "pn": 8}}]}', 1306774370000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5535-ee203', 'stk-user5535', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98387", "n": "Dr. Mesbah Wessam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 203\n\nTerm 141\n\nالتحضير : نهاية الكلاس ، و يسمح بدخولك بعد ١٥ د من بء الكلاس كحد أقصى و من الممكن يطردك اذا جيت بعد أو تحضر بس يحسب لك غياب\n\nطريقة الشرح : من السلايدات و يحل الاكزامبلز على السبورة ، ملك في الشرح ما شاء الله بارك الله ، النوت اللي يكتبها اكتب وراه جدا مهمة\n\nالكويزات : من الاولد اكزام\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالقريد النهائي: A+\n\nالصوت: واضح\n\nإضافات :\n\n- يمنع استخدام الجوال في الكلاس ، و يطردك اذا ثاني مرة\n- أنصح فيه و بقوة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1421916-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mesbah-wessam/98387/26", "user": "user5535", "ts": 1422125885000, "tid": 98387, "pn": 26}}]}', 1422125885000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abaadi-ee203', 'stk-abaadi', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98387", "n": "Dr. Mesbah Wessam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE203\nTerm 202(Online)\n\nالتحضير: يحضر كل حصة مرات في البداية او الوسط وقليل في النهاية\n\nالشرح: طبعا كان يسجل حصصه هو يشرح عادي في مبنى 59 وبعدين ينزلها على قناته باليوتيوب ويقولنا شوفوا المقاطع قبل الحصة ونجي الحصة يراجع الافكار شوية ويشف اذا في اسئلة+ المقاطع ايضا احتوت على امثلة هو يحلها. اضا احيانا كان يقولنا انو نشوف مقطع او اثنين في الحصة نفسها\n\nالكويزات: كوبزاته نوعا ما متوسطة وتقريبا يجيب افكار تشبه اللي يشرحه\nمياجر وفاينل : كومون\n\nالصوت: واضح سواء عربي او انجليزي\n\nالتقييم العام: B+\n\nاضافات: الدكتور كويس ومتساعد لكن طريقته في سالفة انو لازم نشوف المقاطع قبل الحصص كانت صعبة خاصة لما تتكتل وقت المدات او المياجر. بشكل عام الدكتور كويس في الاونلاين بس ممكن في الحضوري افضل وافضل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531509-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mesbah-wessam/98387/32", "user": "Abaadi", "ts": 1630012401000, "tid": 98387, "pn": 32}}]}', 1630012401000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rockwentz-ee203', 'stk-rockwentz', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98388", "n": "Dr. Hassan Ragheb", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ذس لكتشرراااا وير قنا دسكساااا ذا ترانزستوررراااااا 🤠\n\n--\n\nEE203\n\nصراحة المدرس رهيب وما يتفوت وشرحه جييييد … ممكن أحيانًا يدعس في الشرح لكن تلحق عليه\nنظامه عجبني تسلم الهومورك وبعدين ينزل السلوشن والكلاس اللي بعده يعطي كويز على الهومورك وتصحيحه للكويزات والمياجر حلو\n\nالتحضير بشكل يومي ينادي بالأسماء …\n\nأنصح به 🌹 …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1123236-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hassan-ragheb/98388/19", "user": "RockWentz", "ts": 1353788456000, "tid": 98388, "pn": 19}}]}', 1353788456000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6737-ee203', 'stk-user6737', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98388", "n": "Dr. Hassan Ragheb", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أحس إنه المنتدى إذا أحد تكلم على مدرس يجي طالب ويكمل على نفس المنوال\nبصراحة كنت متخوف جداً إني أنزل معاه ولكن ما ندمت أبداً ومن احلى الكلاسات كان كلاسه\n\nee203 - 121\n\nالتحضير :\nآخر كل كلاس ينادي على الأسماء\n\nطريقة الشرح :\nشرح رهييييب جداً ومنظم كثير يشرح الكونسبت ويفهمك كل شي تحتاجه وبعدها يحل أمثلة تفهمك 90% من الكورس\n\nالكويزات :\nسهلة ، تكون عبارة عن أسئلة مشابهة للهوموورك (الهوموورك يكون قبل الكويز على طول)\n\nالمياجر:سهالات إذا هو الكودينيتور أسهل ميجر من دخلت الجامعة وسوى حركة حلوة ميجر 2 كان الأفرج نازل لان غير الأسئلة عن طريقة الأولد اكزام ( بدل مو أنلايزيز وضع سؤال ديزاينينق والطلاب شاطرة بس تعرف تحل ) المهم الطلاب وأنا منهم جبنا درجات نازلة 😭 وقام ووضع ميجر 3 أوبشينال لتحسين ميجر 2 🌺\n\nالفاينلات :ـــــ\nالقريد النهائي:\nA+\n\nالصوت:\nواضح\n\nإضافات :\nالدكتور متساعد جداً إذا تسأله سواء في الكلاس ولا في الأوفس ويشرحلك بالتفصيل ليتأكد إنك فهمت\n\nطبعاً البعض يقول ما عنده أخلاق بس والله أنا أشوفه العكس\nبس باختصار ما يحب الفلسفة والتسليك اللي بعض الطلاب يسووها\n\nأنصح به وبقوة في كورسات الاكترونس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1129971-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hassan-ragheb/98388/20", "user": "user6737", "ts": 1354542554000, "tid": 98388, "pn": 20}}, {"id": "stk-dr-f118662", "n": "Dr. Zaib Alam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ee 203\nباكستاني\nيشرح الإكسبرمنت ويوضحها بشكل مقبول جداً ( أنا أعتبره ممتاز )\nمرن جداً في وقت تسليم الريبوتات والبري لاب\nالكوزات سهلة جداً بس كوزين والهيلب سيشن مفيدة نوعاً ما\nأي وقت تخلص تقدر تمشي وعادة تخلص قبل نهاية الوقت\nأنصح به\nتقييمي له a", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1131425-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-zaib-alam/118662/8", "user": "user6737", "ts": 1354639212000, "tid": 118662, "pn": 8}}]}', 1354542554000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7586-ee203', 'stk-user7586', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98388", "n": "Dr. Hassan Ragheb", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا درست معاه كورسين (121-ee203) و (123- ee340)\n\nصراحة الدكتور جبااااار و يبسط المادة لابعد درجة\nلا يفوتك نزل وانت مغمض\nالقريد a+ وبدون تردد\n\nملاحظة\nاتوقع ان الدكتور غير من طريقته اخر ثلاث سنوان لان اللي الشباب اللي في بداية الموضع يحشون فيه واللي بالاخير يمدحون فيه مدح مو طبيعي وهو يستاهل المدح\n\n(وجهة نظري)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1249242-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hassan-ragheb/98388/28", "user": "user7586", "ts": 1374960865000, "tid": 98388, "pn": 28}}]}', 1374960865000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6130-ee203', 'stk-user6130', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98394", "n": "Dr. Hammi Oualid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله ،،،\nee 203 سمستر 111 ،،،\n\nالشرح : يشرح من سلايدات و شرحه من متوسط إلى أقل من متوسط و عيبه إنه ما يحمسك تفهم.\n\nالتحضير : ينادي الأسماء و نادراً ما ينسى.\n\nالكوزات : سهلة و عطانا 7 كوزات و أخذ احسن 4 كوزات و بصراحة ما قصر معنا في ذا النقطة.\n\nالمياجر و الفاينلات : كومن.\n\nإضافات :\n* الدكتور تصحيحه ما أدري وش يبي يعني يخسف خسف الله يهديه و سوا حركة مخسية في الفاينل و هي حركة boxes يعني يشوف الجواب اللي في البوكس إذا صح يروح يشوف الخطوات إذا خطأ صفر و لا يشوف الخطوات 😲 و اتوقع ذا الحركة بعد سووها في ee 201 .\n* عطانا بروجكت طويل و صعب بس راعنا \" الجروب حقنا \" في الدرجة لأني سمعت إنه عطى قروبات أصفار.\n\nالقريد النهائي : +C .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970944-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hammi-oualid/98394/18", "user": "user6130", "ts": 1326990656000, "tid": 98394, "pn": 18}}]}', 1326990656000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisalcom2008-ee203', 'stk-faisalcom2008', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98402", "n": "Dr. Anas Salhab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لاب EE 203 Term 122\nالتحضير : يحضر بداية الكلاس\nطريقة الشرح : من السبورة واذا ما فهمت يجيك ويشرحه\nالكويزات : سهلة الى متوسطة\nالقريد النهائي: A+\nالصوت: ممتاز وانجليزيته ممتازة\nإضافات : الدكتور شريح وأخلاق وما يتفوت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1250131-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anas-salhab/98402/7", "user": "faisalcom2008", "ts": 1375138175000, "tid": 98402, "pn": 7}}]}', 1375138175000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-black_side-ee203', 'stk-black_side', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98494", "n": "Dr. M.a. Al-Gahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه EE203 في 152\n\nفي البداية مارتحت له لسببين, كانت سلايداته في أول تشابتر فقيرة جداً, تقريبا ماتتجاوز 10 سلايدات لتشابتر كامل , ولا تحتوي على أي مثال فقط رسمات وشروحات بسيطة\n\nوالسبب الثاني والأهم حسيت أن الدكتور عنده مشكلة في الإلقاء وايصال المعلومة حسيته مرتبك نوعاً ما وانجليزيته سيئة\n\nلكن من بعد مادخلنا في تشابتر 3 ( diodes ) تغيرت نظرتي نوعاً ما, سلايداته صارت مليئة بالأمثلة والشروحات الكافية لإيصال المعلومة\n\nصحيح أن الدكتور ماكان ممتاز في إيصال المعلومة, لكن كان يميزه تكرار الشرح واعادته أكثر من مرة لما تدخل المعلومة في راسك بالغصب\n\nوللأمانة أحس مستوى شرح الدكتور كان تصاعدي وتحسن كثيرا مع الوقت وحسيت أني ظلمته بالحكم الأولي\n\nالكويزات عطانا 6 كلها سهلة تقريبا وحذف أسوأهم, عطانا 4 هومووركات من الكتاب وكان يحضر في بداية كل محاضرة بنفسه, توزيع الكلاس وورك ماهو ثابت, هو يغير التوزيع لما يوصل للتوزيع المناسب اللي يخلي الافرج 15 من 20 تقريباً ( هذا على كلامه )\n\nحسابه للغيابات بدأ من ثالث غياب\n\nأعطيه B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450342-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-a-al-gahtani/98494/22", "user": "Black_side", "ts": 1464156650000, "tid": 98494, "pn": 22}}]}', 1464156650000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alialdraimli-ee203', 'stk-alialdraimli', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98494", "n": "Dr. M.a. Al-Gahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE203 Term 152\nالتحضير :\nينادي بالاسماء قبل بداية المحاضرة\nطريقة الشرح :\nيشرح من سلايدات هو مسويها، السلايدات مختصرة جدا يعني ما تنفع تدرس منها ابدا\nالكويزات :\nمستواها سهل\nالصوت:\nالصوت واضح لكن لغته الانقليزية تعبانة\nإضافات :\nالدكتور سيء في الشرح، حسيت اول كورس في الالكترونكس صعب لدرجة عجيبه، ما كنت افهم منه اي شي في المحاضرة بعدين لما درست 303 مع دكنور ثاني بديت احب الالكترونكس\nالدكتورميزته انه متعاون في التصحيح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466220-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-a-al-gahtani/98494/23", "user": "AliAlDraimli", "ts": 1484333369000, "tid": 98494, "pn": 23}}]}', 1484333369000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah2015-ee203', 'stk-abdullah2015', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98494", "n": "Dr. M.a. Al-Gahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه EE203 LECTURE في ترم 172\n\nالتحضير :\nشديد في التحضير، يحضر بداية الكلاس ولو تأخرت 5 دقايق راح يسجلك غايب.\nطبعًا الغرض من هذا الشيء هو عشان الطالب ما تفوته الفائدة من الكلاس.\n\nطريقة الشرح :\nعن طريق سلايدات، ويعلق عليها ويكتب على السبورة نوت مفيدة.\n\nالكويزات :\nالكويزات كانت أفكارها مقتبسة من الهوموورك، فإذا حليت الهوموورك المتعلق بماتيريال الكويز بفهم راح تحل الكويز، وإذا لا فالله يعينك.\nبخصوص الماتيريال الأخير ما كان عليه هوموورك، فكانت الكويزات تجي من الأشياء اللي شرحها في الكلاس.\n\nبشكل عام أقدر أقول إن الكويزات متوسطة تميل إلى السهولة إذا عرفت من أين تؤكل الكتف.\nطبعًا أتكلم عن اللي صار في ترم 172 ومب شرط إن الدكتور يتبع نفس النظام لما يدرّس المادة في سمسترات ثانية.\n\nالمياجر:\nكومون\nتصحيحه للمياجر يعطيك حقك وفي بعض الأحيان أحسه ينقص أكثر مما يجب لما تكون الإجابة صحيحة بشكل جزئي.\nيعني بشكل عام أقدر أقول إنه تصحيح عادي لكن يميل إلى التشدد، وهذا الشيء لاحظته أكثر شيء في الميجر الثاني (وجهة نظر).\n\nالفاينلات :\nكومون.\n\nالقريد النهائي:\nB+\n\nالصوت:\nواضح .\n\nإضافات :\n- الدكتور لا يسمح باستخدام الجوال في أثناء المحاضرة، والغرض من ذلك عشان الطلاب يركزون في المحاضرة.\n- بشكل عام، الإليكترونيكس مادة ثقيلة، فبالنسبة لي أشوف إنه إذا كنت تتابع أول بأول مع المادة راح تفهم معاه، وإذا ما كنت متابع مع المادة ما راح تفهم شيء، والناس قدرات.\n\nفي الأخير أقول، الدكتور محمد القحطاني ممتاز من ناحية الأخلاق والتعامل وكذلك من ناحية الشرح، والخلاصة إني أنصح به.\n\nبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1497999-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-a-al-gahtani/98494/25", "user": "Abdullah2015", "ts": 1534797642000, "tid": 98494, "pn": 25}}]}', 1534797642000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ee_specialist-ee203', 'stk-ee_specialist', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98494", "n": "Dr. M.a. Al-Gahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 172 and Term 181\nEE203 and EE303\nنفس كلام Abdullah2015\nبس\nالمياجر:\nفي التصحيح أشوف إنه متساهل نوع ما.\nالفاينل:\nللمادتين عادة يكون أصعب من المياجر.\nالقريد النهائي:\nA\nإضافة\nعادة تكون المادة حول الاستاندر مع القحطاني لان أغلب الطلاب يجيبون درجات عالية.\nبالنسبة لي أشوفه خيار ممتاز لمواد الإليكترونيكس(EE203&EE303)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504140-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-a-al-gahtani/98494/26", "user": "EE_Specialist", "ts": 1545891079000, "tid": 98494, "pn": 26}}]}', 1545891079000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-am_1421-ee203', 'stk-am_1421', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98494", "n": "Dr. M.a. Al-Gahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE203 ---- ترم 211\n\nالتحضير : كان اول الترم يحضر اول ما يبدأ الكلاس ويعاتب على التاخير … في النهاية ما عاد صار يحضر\n\nطريقة الشرح : يشرح من سلايداته ويحل بالقلم عليها\n\nالكويزات : تقريبا 7 كويزات وكانت بسيطة جدا\n\nالمياجر: كومن\n\nالفاينلات : كومن\nالقريد النهائي: طلعت ب A معاه واعطيه F\n\nالصوت: ما هو مسموع للي ورا بسبب الكمامة وبعدين بدا ينزل الكمامة ونسمع شوي\nإضافات :\n1- شرح الدكتور بالنسبة لي ما كنت افهم منه شيء ابدا\n2- اخلاقه للاسف سيئة جدا معاي شخصيا\n3- يكره احد يمسك الجوال\n4- باقي بين ال A و +A درجة وحدة بس وكان خاسفني في الكلاس وورك بسبب انشطة الكلاس اللي مالها اي نفع + معطينا خمس هومووركات في اقل من نص الترم مع انه المفترض يحطها طوال ترم وضغطني جدا مع انها بسيطة .\n\nنصيحتي لك اذا انت طالب تبغى تطلع بقريد كويس ,الدكتور هذا ما راح تستفيد منه ابدا.\nلا انصح به ابدا (بناء على تجربتي الشخصية)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533429-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-a-al-gahtani/98494/28", "user": "AM_1421", "ts": 1642013810000, "tid": 98494, "pn": 28}}]}', 1642013810000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8577-ee203', 'stk-user8577', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98496", "n": "Dr. Husain Al-Zaher", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ee203\nبنود التقييم :\n\nالتحضير : بداية الكلاس بالسيريال نمبر.\n\nطريقة الشرح : يستخدم نوته على البروجكتر مع السبورة … الدكتور جدا شريح و فاهم المادة و مشاكل الطلاب في المادة كويس لدرجة السؤال يجي في بالك شوي تلقاه جاوبه وهو يشرح.\nلا تطلع من الكلاس مو فاهم هذي قاعدته.\n\nالكويزات : أغلبها سهلة … بعضها من النوت نسخ لصق.\n\nالمياجر: كومن … بس هو كان الكوردنيتر وكان مستواها متوسط.\nالفاينلات : كومن … الدكتور يعشق شي اسمه كونسبت فجاب لنا اسئلة كونسبت في الفاينال كسر روسنا فيها 🥊 🥊\n\nالصوت: واضح.\n\nإضافات :\nالدكتور يكره الغياب جدا … يحب اللي يجلس قدام واللي يروح له المكتب … التصحيح يعطيك حقك بلا زيادة بس أكبر ميزة أنه من أسرع الدكاترة في التصحيح وما يتأخر على الطلاب.\n\nشخصيا كنت شايف الدكتور ممتاز إلى الفاينال … حسيت انه زودها في الكونسب … أتوقع جازما أن بعض الدكاترة اللي كانوا يدرسوا السكاشن الثانية لو عطيتهم بعض هالاسئلة ما حلوها.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1382661-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-zaher/98496/17", "user": "user8577", "ts": 1403742385000, "tid": 98496, "pn": 17}}]}', 1403742385000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10177-ee203', 'stk-user10177', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98496", "n": "Dr. Husain Al-Zaher", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم\n\nee 203\n\nالدكتور هذا عنده مشكلة كبيرة اللي هي يشرحلك شرح بسيط جدا و يحسسك إن المادة سهلة لكن تنصدم في الفاينل\n\nشرحه ملخبط مرة على الكمبيوتر و مرة يكتب على السبورة و كل شوي يغير في الصور\n\nتصحيحه في نظري ممتاز و اختباراته سهللللة جدا\n\nأخلاقه غريبة مرة يكون طيب على الآخر و في الغالب طفشان و معصب\n\nأعطيه c+\n\nبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1382849-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-zaher/98496/18", "user": "user10177", "ts": 1403811652000, "tid": 98496, "pn": 18}}]}', 1403811652000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8714-ee203', 'stk-user8714', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98496", "n": "Dr. Husain Al-Zaher", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت مع الدكتور كورس ee203\n\nبنود التقييم :\n\nالتحضير :\nيحضر بنهاية الكلاس وينادي على الأرقام, وبعض الاحيان يسحب على التحضير.\n\nطريقة الشرح :\nللأمانة الدكتور متميز جدًا بالمادة, ويحب أن الطلاب يجوه للمكتب يسألوه وكذا …\nمشكلته أنه يشرح بسرعة ولازم تسأله بكل جزئية ولا بتعدي عليك ومابتفهم الي بعدها.\n\nالكويزات :\nمتنوعة, أغلب الاحيان تكون سهلة, ونادرًا ماتكون صعبة !\n\nالمياجر:\nكومن ( مستواها متوسط )\n\nالفاينلات :\nبالترم تبعنا الفاينل جاء صلللللللللللخ, اتعودنا في المياجر على اسئلة حسابية لكن بالفاينل أغلب الاسئلة كانت كونسبشول !!!\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح ولغته الانجليزية جيدة\n\nإضافات :\nالدكتور ممتاز جدًا, صحيح بعض الاحيان تعامله مع الطلاب مايكون كويس خصوصا لما تسأله سؤال يحاول يظهر لك أن سؤالك من السهولة بمكان بحيث لا يستحق أن تسأله!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1389620-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-zaher/98496/19", "user": "user8714", "ts": 1407956019000, "tid": 98496, "pn": 19}}]}', 1407956019000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-ee203', 'stk-user8581', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98496", "n": "Dr. Husain Al-Zaher", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 203 - TERM 142\nالتحضير : بعد بداية الكلاس بخمس دقايق تقريبا واحيانا بعد مايخلص من شرح نقطة معينة يبتدي في التحضير بالسيريال نمبر … + يسمح بالميك اب\n\nطريقة الشرح : عنده نوتة خاصة فيه ويشرح منها على البروجكتر ونفس الوقت يستخدم السبورة لحل المسائل وتوضيح الافكار … وانصح الي منزله عنده ركز معاه في كل شي يقوله ولو تكتب بعض النقاط الي يذكرها خصوصا الاخطاء الي دايما يسونها الطلاب يكون أفضل لأنه في المياجر عدد مب قليل من المسائل الكونسبت قدرت احلها بسبب بعض الملاحظات الي يذكرها وسط الشرح فحاول تكتب معاه خصوصا النقاط الي تحسه يركز عليها. الدكتور له خبرة طويلة في الكورس فلو واجهت مشكلة او كانت درجاتك سيئة في الميجر الأول مثلا راجعه وهو ما راح يقصر متعاون بشكل كبير.\n\nالكويزات : سهلة جدا وتكون من النوتة او من سؤال في الهومورك لكن بشكل مبسط لأن مدة الكويز 10 دقايق او ربع ساعة بالكثير. فلا تضيع الكلاس ورك !\n\nالمياجر**: كومون + نسبة مب قليل من الاسئلة تكون conceptual**\nالفاينلات : كومون لكن انتبه منه واستعد له اكثر من المياجر\nالقريد النهائي : a كشرح و a+ كتعاون وتعامل مع الطلاب و استغرب من الي يذم اخلاقه ( يمكن تغير )\n\nالصوت**:** واضح\nإضافات :\n- نوته جيدة لكن نوعا ما ملخبطة وما تصلح الا للي منزل معاه المادة … فحاول تركز معاه في الكلاس عشان تعرف المواضيع الي داخلة في الكورس .\n- يتضايق من الطلاب الي ينشغلون بالجوال او ينامون فأحيانا يعطيهم كم سؤال او يقعد ينصح الطلاب بشكل عام .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1422982-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-zaher/98496/21", "user": "user8581", "ts": 1437935237000, "tid": 98496, "pn": 21}}]}', 1437935237000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ma7mud-ee203', 'stk-ma7mud', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98496", "n": "Dr. Husain Al-Zaher", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 181 EE 203\n\nالتحضير : بداية المحاضرة، احيانا بالنص، ما يدقق على التأخير ويسمح تدخل إذا متأخر. يحضر عن طريق SN\n\nطريقة الشرح : يشرح من مذكره له، المذكرة ليست شاملة وفيها اشياء كثيرة تحتاج شرح الدكتور، لازم تركز معاه في المحاضرة عشان تفهمها، جزئية الاختبار الثاني مافي عليها اسئلة والشرح مختصر جدا لها\nبشكل عام الشرح جيد جدا لكنه ملخبط، المنهج قصير وراح تكون نص المحاضرات بدون هدف وأعطانا اكثر من off، الدكتور ممكن يستفيد اكثر من وقت المحاضرة لكن حسيت غالبه يروح ع الفاضي.\n\nالكويزات : سهلة ومباشرة، بعضها من الاختبارات السابقة\n\nالمياجر والفاينل:سهلة ومافيها اي تريكات وبسيطة، دايما يقول شباب لا تركزو الا على الأشياء اللي اشرحها وراح تكون الأسئلة سهلة، لكن تصحيحه نوعا ما شديد.\n\nالقريد النهائي: B+\nالصوت: نوعا ما منخفض، الدكتور حسيته ما يشرح بنفس الفصل هذا\n\nإضافات : الدكتور محترم وحبيب ومتعاون جدا جدا، اختبارات سهلة ويعطي اكثر من محاضرة off، المنهج قصير، دايما يقول اسئلتي من الشرح ومباشرة وما احاول اجيب اسئلة صعبة ع الطلاب، لكن مشكلته “اتوقع” الفصل هذا ما كان بالمود، الشرح الى حد ما ملخبط، ونص المحاضرة تضيع ع الفاضي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504407-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-zaher/98496/25", "user": "Ma7mud", "ts": 1546423763000, "tid": 98496, "pn": 25}}]}', 1546423763000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-muntathir111-ee203', 'stk-muntathir111', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98496", "n": "Dr. Husain Al-Zaher", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM-192-EE203\nالتقييم قبل الكورونا\nالتحضير : عادة نهاية الكلاس برقم السيريال بالكشف\nطريقة الشرح : باستخدام البروجكتر ويحل على السبورة\nطبعا الدكتور فاهم جدا ومتمكن بالمادة بس ماكانت المعلومة توصل بالشكل المطلوب من وجهة نظري\nالكويزات : سهلة وبسيطة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت:ممتاز\nإضافات :\nالدكتوور اخلاقه عالية جدا وكان اكثر دكتور تساعد معانه يوم صار الوضع اونلاين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525216-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-zaher/98496/26", "user": "Muntathir111", "ts": 1598718235000, "tid": 98496, "pn": 26}}]}', 1598718235000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-some_ee-ee203', 'stk-some_ee', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98496", "n": "Dr. Husain Al-Zaher", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM-212-EE203\n\nالتحضير : كان ما يحضر اول 6 اسابيع ثم صار يحضر بالرقم اذا شاف العدد قليل، حذف 3 غيابات وبعدها خصم 0.5 على كل غياب. يحرص ان الطالب يحضر معه عشان يفهم\nطريقة الشرح : يعرض سلايداته ويقعد يكتب فوقها وأغلب الشرح يكون نظري فقط ما يكتب كثير وأنت تخيل معه. يشرح بسرعة فكان صعب أنك تاخذ معه نوتات خلال الكلاس وبنفس الوقت تركز وتفهم. شيء اسطوري في الدكتور أنه بيعطيك كيف تبدأ حل السؤال لكن ما بيحل معك ولا شي الا في كلاس واحد قبل الميجر يحل أسئلة. عموما الدكتور جيد في الشرح لكن نوتاته ما تفهم منها شي لو رجعت لها ولا تقدر تكتب نوتات معه فكان لازم ارجع لمقاطع د. مصباح.\nالكويزات : سهلة أغلبها تكون من الأمثلة اللي بالنوت حقه وشيء بسيط ما يبيك تحل بالأرقام مثلا أحد الكويزات قال بس اكتب الKVL. أفرجنا كان أفرج المادة لا نقصنا ولا زدنا بالنورماليزيشن.\nالمياجر: كومن، بس قال عن أسئلة هو جابها أو يحب أنها تجي في الاختبار وأغلبها متعلق بالفهم للإلكترونيات وتطبيقها.\nالفاينلات : كومن\nالقريد النهائي: C\nالصوت: عالي بتسمعه حتى لو أنت بآخر الكلاس\n\nسلبيات واجهتها عند الدكتور:\n\nفجأة بنص الشرح يبدأ يسولف ويحكي قصص وينكت لمدة 5-10 دقائق وبعدها على طول يرجع يكمل شرح فما تدري وين كنت وايش صاروتضيع\nالدكتور ما هو واضح من بداية الترم وحصل أكثر من موقف يغير اللي قاله لنا، مثلا بالبداية قال ما في خصم على التحضير ثم على الاسبوع ال10 سأله واحد بالإيميل ورد عليه أنه بيخصم، مواعيد الكويزات والواجبات غير منتظمة أخذنا 4 كويزات من اصل 5 في اول 9 اسابيع وكذلك الواجبات، فجأة قال يبغى بحث ثم غير رأيه وكذا.\nتصحيح الدكتور سيء وكذلك غير واضح في منهج التصحيح، لو في سؤال يعتمد على سؤال قبله وأنت أخطأت في الأول بيخصم عليك مرتين، يدقق على أشياء غريبة في الكويز والميجر مثال: خصم علي في كويز لأني كتبت شي خطأ في هامش الورقة على أن الإجابة النهائية صحيحة، في المياجر كان يخصم نصف درجة السؤال اذا شاف عندك خطأ في الديزاين مهما كان صغير أو كبير.\nالدكتور ما نزل درجة الكلاسوورك ولا توتل وعلى طول نزل القريد في البورتل.\nللأسف اخلاق وتعامل الدكتور ما كان نفس المذكور في المنتدى، حصل أكثر من موقف يتنمر على طلاب أو عامل نظافة، ما يرد على الايميلات الا متأخر مرة ولازم تراجعه اسبوع عشان يحل مشكلتك وأحيانا ما يحلها.\nوحصل موقف بنهاية الترم حسب الكلاسوورك خطأ وبناء عليه نزلت قريد عن المتوقع وجالس اراسله ايميل ولا حصلت أي رد وهذا الأمر كان ممكن يتم تفاديه لو نزل الكلاسوورك في البلاكبورد.\n\nإيجابيات عند الدكتور:\n\nفاهم ما شاء الله وبيفيدك بأنك تشوف الصورة الأكبر للكورس وايش فائدة الالكترونيات\nيلغي حصص كثير ويترك حصة قبل الميجر عشان تعرضوا أسئلتكم ويحلها (ما بيحل شي من عنده جيب سؤالك ولا بيقعد ينبهكم نص الكلاس أن ذا غلط ولازم تراجعوا)\nيصحح بسرعة سواء كويزات أو مياجر\nهذه الإيجابيات والسلبيات اللي ممكن تتفق معها أو لا حسب إيش تفضل، لكن باختصارعن نفسي ما بنزل عند الدكتور أبدا لو أتأخر ترم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534513-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-zaher/98496/27", "user": "Some_EE", "ts": 1653901708000, "tid": 98496, "pn": 27}}]}', 1653901708000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-breaktheunbreakable-ee203', 'stk-breaktheunbreakable', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98497", "n": "Dr. Ma Al-Absi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني 183 - مادة EE203 - لاب ولكشر\n\nالتحضير : شديد في التحضير. يحضر أول دقيقتين، إذا تتأخر أكثر من 5 دقائق تكون ليت وأكثر من 10 دقائق غالبا غائب. يحفظ الطلاب ويعرفهم. ويزعل إذا أحد يحضر أحد والخ… نظامي بزيادة الزبدة.\nطريقة الشرح : شرحه غريب. مرات تفهم ومرات ما تفهم، يشرح من عدة سورسز، يشرح أشياء ما لها دخل في المنهج ويحب يسوي درفيشن وتعقيد في الشرح. في الدروس السهلة ممكن تفهمه وممكن لا وفي الصعبة الشرح أنت وحظك.\nالكويزات : فيها صعوبة وعليها نسبة كبيرة من المنهج\nالمياجر: الأول سهل، الثاني صعب\nالفاينلات : صعب وجاب أشياء ما درسنا إياها\nالقريد النهائي: أعطيه C+ أو C\nالصوت: مفهوم ومسموع\nإضافات :\n\n1- تصحيح الدكتور إذا حلك صح بتحصل إذا غلط بتنقص. ما في زيادة أو تنقيص عنده.\n2- تصحيح اللاب شديد وسريع وما يركز في تعب الطلاب\n3- توزيع درجات المادة أشعر مب عادل، أغلب الكلاس أتوقع طلع ببين C و B وكانوا أغلبهم فاهمين كثير في المادة.\n4- الدكتور ما يرد على الإيميل\n5- مرات غير موجود في الأوفيس أورز\n\nبصراحة ما أنصحك تنزل عنده، المادة تعتمد بشكل كبير على المدرس نفسه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513335-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ma-al-absi/98497/13", "user": "BreakTheUnbreakable", "ts": 1564923335000, "tid": 98497, "pn": 13}}]}', 1564923335000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11743-ee203', 'stk-user11743', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98497", "n": "Dr. Ma Al-Absi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت عنده EE203-183 لاب ولكتشر\n\nالتحضير: شديد جدا في التحضير، وقفط كم واحد في التحضير الإلكتروني\n\nالشرح: متوسط إلى ممتاز، لكن تحتاج ترجع تذاكر بنفسك، لأن فيه نقاط ما يركز عليها.\n\nالأخلاق: الرجل متواضع وحبيب وأخلاقه جميلة جدا.\n\nالساعات المكتبية: غالبا ما يكون متواجد، وما يحبها أبدا.\n\nالكويزات: متوسطة إلى فوق المتوسط، غالبا من أسئلة الكتاب أو من الشرح.\n\nالدرجات: يحتاج أنك تبين للدكتور حرصك واجتهادك و تقدر تطلع معاه بقريد ممتاز\n\nفالكم التوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1514170-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ma-al-absi/98497/14", "user": "user11743", "ts": 1566816340000, "tid": 98497, "pn": 14}}]}', 1566816340000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hms812-ee203', 'stk-hms812', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98499", "n": "Dr. Yaqub Mahnashi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "181- EE203 lab\nالدكتور رجع الجامعة ك assistant professor\nبسم الله نبدأ\n\nطريقة الشرح: يبدأ اللاب بتذكير بسيط للtheory في اللكشر ويربطها مع تجربة اليوم ثم يبدأ يشرح التجربة، شرحه ممتع ، يشرح بشكل مختصر وشرحه يكون كافي ووافي للي بنسويه في التجربة الدكتور ماشاء لاقوة الا بالله ماقد سألته سؤال ولا جاوبني\n\nالكويزات: ثلاث كويزات مستواها متوسط يميل الى السهولة تركز على شغل اللاب\n\nالفاينل: كان ملتبل شويس سهل بالنسبة للنظري والتطبيقي كان برضو سهل وحدة من التجارب الماضية\n\nالتصحيح: ممتاز جداً و واضح\n\nإضافات: الدكتور بطل ياأخوان مايتفوت أبد\nمع انه كان يدرسني لاب الا إنه كان يستقبل أسئلة اللكشر في الأوفيس بكل صدر رحب الله يوفقه وين ماكان", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503850-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqub-mahnashi/98499/11", "user": "HMS812", "ts": 1545326478000, "tid": 98499, "pn": 11}}]}', 1545326478000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ee203', 'stk-guest', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98527", "n": "Dr. Sharif Sheikh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه EE203 الفصل 201 اون لاين\n\nالتحضير :\nيأخذ صورة للحضور بزوم غالبًا بنص المحاضرة وما كان شديد عليه كان واضع تنبيه صوتي لدخول الطلاب ويسأل عن سبب التأخير وما أتذكر أنه حاسب طالب على التأخير.\n\nطريقة الشرح :\nشرحه يكون من سلايدات ويكتب بإستخدام البورد ممل جدًا وملخبط ، الدكتور قال لنا أنه ما درس المادة من فترة فكان شرحه فيه الكثير من الأخطاء ينتبه لبعضها ويصلحه أثناء المحاضرة وينبهه بعض الطلاب عليها ، السلايدات كانت جيدة بالنسبة لي لكثرة الأمثلة اللي تغنيك عن فتح الكتاب لكن فيها بعض الأخطاء بالحلول ايضًا.\n\nالكويزات :\nهنا كانت اسوأ نقطة الدكتور كان مقسم الاختبارات لكويزات وكلاس ورك وأنا ما أشوف اختلاف فيهم صراحة لكن كل وحدة لها درجاتها الخاصة ، كان اول كويز و كلاس ورك ماشين كويس لكن في طلاب الله يسامحهم طلبوا من الدكتور يغير عن اسئلة الاختياري وللأسف خذ بنصيحتهم وهنا طاح افرج الطلاب بشكل كبير جدًا لأن الدكتور حاط لنا اسئلة رتن بشكل فراغي بحيث تكتب الجواب عن طريق البلاك بورد كاملًا بالخطوات بالإضاقة لعوامل ثانية ايضًا مثل أن الدكتور كان يحط كويزات بمعطيات ناقصة وما ينبهنا الا بنص الكويز وغير ضيق الوقت بكويزاته كان الوضع حوسه ، نهاية الموضوع عشان الافرج اضطر انه يرفع الطلاب ما يقارب 5 درجات بسبب الافرج الطايح.\n\nالمياجر:\nكومن واستبدلوا المياجر بميد وكان الاختبار معقول الاسئلة منوعة من ناحية اختياري و جواب نهائي و سؤال واحد رتن سوينا سكان لحلنا ورفعناه على البلاك بورد وكان الغالب على الأختبار هو الجواب النهائي + كان في اضافة من الدكتور ان نسوي سكان لكل حلنا ونرفعه عشان لو طالب صارت عنده مشكلة او شي.\n\nالفاينلات :\nكومن وكان معقول ايضًا من ناحية الصعوبة ، كان مقسم لقسمين نفس فكرة الميد منوع من ناحية الاسئلة يغلب عليها الجواب النهائي.\n\nالقريد النهائي:\nالحمدلله طلعت بقريد A+ لكن والله كانت جهد خارجي من بحث عن مصادر للشرح غير الدكتور والحمدلله كان في مصادر متنوعة وفادتنا.\nتقييمي لدكتور هو B من ناحية الشرح اراعيه بسبب الاون لاين لكن من ناحية الكويزات صراحة لعب فينا.\n\nالصوت:\nواضح.\n\nإضافات :\n\nالدكتور متساعد ومتجاوب مع الطلاب حتى لو ما قبل عذرك يبرر لك ليش ما قبل عذرك بالإضافة أنه حريص على الطالب بشكل مزعج ودائمًا يعطي نصايح لكنه كويس ، بصفة عامة من اللي شفته بالمنتدى انصحك تنزل عنده بترم عادي لكن بترم اون لاين نصيحة ابعد عنه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527691-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sharif-sheikh/98527/21", "user": "Guest", "ts": 1610075544000, "tid": 98527, "pn": 21}}]}', 1610075544000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ria-ee203', 'stk-ria', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f98527", "n": "Dr. Sharif Sheikh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE203\nالتحضير :عن طريق ورقة يمررها وتوقع (وتشوف غياباتك منها)\nطريقة الشرح : يشرح بسلايداته ويحل اسئلة الواجب\nالكويزات : كويزات سهلة\nالمياجر: كومن (تصحيحه حقاني ويعطيك زياده اذا شافك فاهم)\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: صوته واضح ومفهوم (هندي)\nإضافات : الدكتور متفهم لوضع الطلاب ويساعدهم ومرات حتى بنص الكلاس يعطيك قصة وينبهك اذا درجاتك سيئة ويتناقش معك وما يبغى يخلي الكلاس بشكل كله فهم مرات يرمي كم من نكته يغير جو الطلاب ويكمل + افضل شيء قد شفتها له الواجب ينزله لك مع الحل ويقول لك حاول تحله اذا ما عرفت شوف حله بس اهم شيء تفهم وهذا شيء مره انا فادني وساعدني بالميجر مره حتى الكويزات اللي يجيبها مرات نسخ لصق من الهوم ورك بالراحة من افضل الدكاتره اللي درسني كهرب وان شاء الله ناوي اكمل معه بكورسات ثانية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535699-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sharif-sheikh/98527/23", "user": "RIA", "ts": 1666941428000, "tid": 98527, "pn": 23}}]}', 1666941428000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-ee203', 'stk-mr.a1', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f172584", "n": "Dr. Abdullah Othman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كنت بخليها نهاية الترم ، بس دام فيه أحد يسأل أوكي\n\nTerm 162\nEE 203 Lab\n\nالتحضير :\nبعد ما يخلص شرح للتجربة يعد الطلاب ، وإذا شاف فيه نقص حضّر بالأسماء. تقريبا بعد ربع ساعة من بداية اللاب.\n\nطريقة الشرح :\nيعبي السبورة بالقوانين والرسومات وكل اللي يحتاجه ، ويبدأ يشرح الكونسبت حق التجربة كاملة. إذا كان فيه شيء جديد أو أداة جديدة يطلعها قدام الطلاب ويوضح طريقة التعامل معها وبعض الأشياء اللي لازم تنتبه لها. واضح جدا في اللي يبغاه في الريبورت (بفصل فيه في الإضافات).\nممكن النقطة السلبية فيه إن شرحه أحيانا ما يكون واضح ١٠٠٪‏ ، لكنه جيد.\n\nالكويزات :\nأعطانا لحد الحين كويزين ، مستواها سهل نسبيا. تصحيحه دقيق اشوي في الكويزات ، بعكس الريبورتات والبري لابات.\n\nالمياجر:\n-\n\nالفاينلات :\nما اختبرنا للحين.\n\nالقريد النهائي:\nمن +B إلى A\nالصوت:\nواضح. الآكسنت كويسة لكن مشكلته ما هو طلق مرة في التحدث لكنه جيد.\n\nإضافات :\nبالنسبة للريبورتات ، راح يرسل ملف كل أسبوع عبارة عن صفحة وحدة على الوورد فيها جداول وأسئلة ، تطبعها وتجيبها معك وتعبيها. مرة وحدة بس طلب منا ريبورت كامل ، وأعطانا اسبوع للتسليم.\nالبري لاب نفس الكلام ، يرسل لك الملف على البلاك بورد وتحله وتطبعه وتجيبه معك.\nالأستاذ خلوق ودايما مبتسم ، ومهما تسأله في اللاب راح يجاوبك بدون ما يتملل من أسئلتك.\nبشكل عام أستاذ عبدالله عثمان كويس ، وإذا ما حصلت أفضل منه راح يكون خيار جيد في اللاب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1472257-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-abdullah-othman/172584/3", "user": "Mr.A1", "ts": 1493573821000, "tid": 172584, "pn": 3}}, {"id": "stk-dr-f99452", "n": "Dr. Muhammad Taher Abuelma''atti", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "عالم في مجاله ، وأشوف أنه فوق التقييم من الناحية العلمية. لكني فضلت أكتب حتى أوضّح بعض الأمور بحكم أنه أستاذ في القسم.\n\nTerm 162 EE 203\n\nالتحضير :\nما فيه تحضير ، أنت مسؤول عن نفسك إذا تبي تحضر أو لا. ما يدقق على موضوع التأخير أبد.\n\nطريقة الشرح :\nكاملة على السبورة. يوضح الأشياء اللي تحتاج تخيّل بالرسم ، ويعطيك تطبيقات عملية للأشياء اللي يشرحها. باختصار يعاملك كمهندس.\nترتيب الدروس عنده مختلف اشوي عن بقية الدكاترة. يبدأ ٩ محاضرات شروحات فيزيائية لكل الأجهزة الأساسية اللي بيستعملها في المادة ، بعدين ينخرط في نفس ترتيب المنهج عند باقي الدكاترة. يضيف أشياء من عنده مو موجودة عند الباقي ، يحذف أشياء يشوف إن ما لها داعي. تقدر تقول المنهج مختلف اشوي لكن المعلومات اللي بتطلع بها هي نفسها.\nحل المسائل قليل في المحاضرة. (بتكلم عنها في الملاحظات).\n\nالكويزات :\n٤ كويزات طول الترم ، كل واحد عليه ٢,٥٪‏ ، يحدد موعد الكويز مع الطلاب مع الماتيريال ، وقبله بمحاضرة أو محاضرتين يعطيك Old Quiz عشان يساعدك في المذاكرة.\n\nالمياجر:\nبالعادة مياجر المادة كومون ، لكن د. محمد أبو المعاطي يكتب مياجره لحاله. ميجر ١ كان شيء سهل جداً وثلث السكشن جابوا فل مارك. ميجر ٢ كان مستواه اعلى اشوي لكن الدرجات كانت حليوة.\nونفس الكويزات ، قبل الميجر يعطيك Old Major تتدرب عليه.\n\nالفاينلات :\nنفس نظام المياجر ، كان متوسط مائل للصعوبة وفيه أسئلة تصميم.\nأعطانا Old Final عشان نتدرب عليه ، وأشوف مستواه ما يقارن باللي جابه لنا.\n\nالقريد النهائي:\nA+\n\nالصوت:\nصوت واضح ، الشرح مخلوط بين العربي والانجليزي.\n\nإضافات :\n١. ما عنده هوموركات أبد.\n٢. إذا كانت عندك قارورة ماء انتبه تشرب منها في الكلاس ، ترى يعصّب 😆.\n٣. يسوي ٣ toturials خلال الترم ، لكن هالترم ما اسعفه الوقت وسوى ٢. تجي خارج وقت الكلاس لمدة ساعتين ونص إلى ثلاث ساعات ، يشرح فيها مسائل كثيرة. لذلك هو ما يحل كثير في الكلاس.\nيوزع أوراق الـ toturial قبل بكم يوم وفيها كل الأسئلة -مو محلولة- ، وأنت اللي عليك تجيبها معك وتتابع معه وهو يحل ، وأنقل الحل لو تبي.\n٤. نظام القريدات مختلف عن باقي الدكاترة ، ستاندرد.\nيوزع القريدات بالطريقة التالية:\nA+ >= 95\nA >= 85\nB+ >= 80\nB >= 75\nC+ >= 70\nC >= 65\nD+ >= 50\nD >= 40\nF < 40\n\nعموما ، القريد مقدور عليه مع د. محمد أبو المعاطي ، لكنك تحتاج تفهم المادة مضبوط وما تضيّع درجات اللاب ؛ لأنه ما يقدر يعدّل فيه شيء. تبقى اختبارات الليكتشر هذه بيدك.\n\nهنا رابط فيه الملفات المتوفرة معي حاليا ، إذا فيه شيء جديد راح أضيفه عليهم:\nhttps://drive.google.com/open?id=0B_PxyCxMLG7lNy1IUFZDY21Oc0U", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473818-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-taher-abuelmaatti/99452/10", "user": "Mr.A1", "ts": 1495704173000, "tid": 99452, "pn": 10}}]}', 1493573821000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abbas_tesla-ee203', 'stk-abbas_tesla', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f115342", "n": "Dr. Hussam Al-Shamary", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "192- EE 203 Lab\n\nالتحضير : بعد 5 دقايق تقريبا ، مالاحظت ان يكلم المتأخرين\nطريقة الشرح : يشرح على السبورة شوي وبعدها يروح يشرح عملي تخلص شغلك وتمشي\nالكويزات : قبل الكرونا ماخذنا كويز ،الاون لاين خذنا كوزين تقريبا تعويض في القانون وامورك في السليم بس لازم تكون فاهم السيركت وفاهم الليكتشر مضبوط\nالفاينلات : نفس مستوى الكويزات وبعض الاسئلة جات من نفس الكويزات\nالقريد النهائي: B\nالصوت: مسموع ، اكسنت امريكي ماعجبني.\nإضافات : الدكتور متعاون جدا الريبورت تسويه في البيت وتجيبه ولو عندك عذر ممكن يأخر لك التسليم اسبوع زيادة.\nكان في مشكلة في البريلاب ماكان مفهموم (من المانيوال) الدكتور حاول يشرحها قبل اسبوع ويعطينا المطلوب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525205-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hussam-al-shamary/115342/5", "user": "Abbas_Tesla", "ts": 1598700625000, "tid": 115342, "pn": 5}}]}', 1598700625000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman.h-ee203', 'stk-abdulrahman.h', 'EE 203', 'doc', '{"docs": [{"id": "stk-dr-f118661", "n": "Dr. Eyas Alsuhaibani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ee 203 lab - 112\n\nالأستاذ أخلاق وتعامل أخوي إلى حد كبير … تصحيحه جيد لا هو المتشدد مرة ولا هو اللي يصحح تمشية حال بس .\nكويزاته منطقية ليست صعبة .\nفاهم بس شرحه متوسط بصراحة … يعني يحس ان الطلاب فاهمين ومافي شي يقدر يقوله ، وكل شوي يقول فاهمين ياشباب ؟\nيحب يتكلم عربي … بس إذا في طالب أجنبي يحاول يتكلم انقلش أغلب الوقت …\n\nاللاب كان خفيف وجميل معه . أنصح به الله يوفقه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1123222-ee203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-eyas-alsuhaibani/118661/6", "user": "Abdulrahman.H", "ts": 1353787076000, "tid": 118661, "pn": 6}}]}', 1353787076000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
